import zipfile

with zipfile.ZipFile('sales_data.xlsx') as z:
    print(z.namelist())
    shared = [n for n in z.namelist() if 'sharedStrings' in n]
    if shared:
        print(z.read(shared[0]).decode('utf-8')[:2000])
    for n in z.namelist():
        if 'sheet' in n and n.endswith('.xml'):
            print("---", n)
            print(z.read(n).decode('utf-8')[:3000])

